alt:
import json


def save_progress(path, data):
    f = open(path, "w")
    f.write(json.dumps(data))
    f.close()


def load_progress(path, default=None):
    try:
        f = open(path)
    except FileNotFoundError:
        return default
    data = json.loads(f.read())
    f.close()
    return data
